// HikariCP: maxPoolSize = max_concurrent_queries
// If 200 threads make DB calls: maxPoolSize >= 200
// If < 200: threads wait for connections → timeout → errors!
// spring.datasource.hikari.maximum-pool-size=200

// ═══ SAFEGUARD 2: Rate limiting ═══
RateLimiter rateLimiter = RateLimiter.of("creditBureau",
    RateLimiterConfig.custom()
        .limitForPeriod(500)           // max 500 calls
        .limitRefreshPeriod(Duration.ofSeconds(1))  // per second
        .timeoutDuration(Duration.ofMillis(100))    // wait 100ms for permit
        .build());
// Excess calls: wait or rejected → prevents overwhelming downstream

// ═══ SAFEGUARD 3: Timeouts ═══
supplyAsync(() -> callCreditBureau(), ioPool)
    .orTimeout(5, TimeUnit.SECONDS);  // fail fast if slow!

// ═══ SAFEGUARD 4: Circuit breaker ═══
CircuitBreaker cb = CircuitBreaker.of("creditBureau",
    CircuitBreakerConfig.custom()
        .failureRateThreshold(50)          // open at 50% failure rate
        .waitDurationInOpenState(Duration.ofSeconds(60))  // stay open 60s
        .slidingWindowSize(100)
        .build());
// Open state → all calls fail fast (10ms) → no load on downstream!

// ═══ SAFEGUARD 5: Bulkhead (bounded pool per downstream) ═══
ExecutorService creditBureauPool = new ThreadPoolExecutor(
    10, 20, 60, TimeUnit.SECONDS,
    new LinkedBlockingQueue<>(100));  // max 120 concurrent to bureau!
// Even with 1000 req/s: max 120 concurrent to bureau!
