package com.bank.fanout;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class FanOutAmplificationTest {

    // ═══ Fan-out: N requests × K calls = N×K downstream ═══
    @Test
    void fanOut_amplification() throws InterruptedException {
        int incomingRequests = 100;
        int fanOutPerRequest = 3;
        AtomicInteger downstreamCalls = new AtomicInteger(0);
        ExecutorService pool = Executors.newFixedThreadPool(20);
        CountDownLatch done = new CountDownLatch(incomingRequests);

        for (int i = 0; i < incomingRequests; i++) {
            pool.submit(() -> {
                // Each request fans out to 3 downstream calls:
                CompletableFuture.allOf(
                    CompletableFuture.runAsync(() -> { downstreamCalls.incrementAndGet(); }, pool),
                    CompletableFuture.runAsync(() -> { downstreamCalls.incrementAndGet(); }, pool),
                    CompletableFuture.runAsync(() -> { downstreamCalls.incrementAndGet(); }, pool)
                ).join();
                done.countDown();
            });
        }
        done.await(30, TimeUnit.SECONDS);

        assertThat(downstreamCalls.get()).isEqualTo(incomingRequests * fanOutPerRequest);
        System.out.println("Incoming: " + incomingRequests + ", Downstream: " + downstreamCalls.get());
        // 100 incoming → 300 downstream! 3x amplification!
        pool.shutdown();
    }

    // ═══ Bounded pool prevents overwhelming downstream ═══
    @Test
    void boundedPool_limitsDownstreamConcurrency() throws InterruptedException {
        AtomicInteger maxConcurrent = new AtomicInteger(0);
        AtomicInteger currentConcurrent = new AtomicInteger(0);
        Semaphore downstreamLimit = new Semaphore(10);  // max 10 concurrent!
        ExecutorService pool = Executors.newFixedThreadPool(50);
        CountDownLatch done = new CountDownLatch(100);

        for (int i = 0; i < 100; i++) {
            pool.submit(() -> {
                try {
                    downstreamLimit.acquire();  // rate limit!
                    int c = currentConcurrent.incrementAndGet();
                    maxConcurrent.updateAndGet(m -> Math.max(m, c));
                    Thread.sleep(50);  // simulate downstream call
                    currentConcurrent.decrementAndGet();
                } catch (InterruptedException e) { }
                finally { downstreamLimit.release(); done.countDown(); }
            });
        }
        done.await(30, TimeUnit.SECONDS);

        assertThat(maxConcurrent.get()).isLessThanOrEqualTo(10);  // never > 10!
        pool.shutdown();
    }

    // ═══ Timeout prevents thread hang ═══
    @Test
    void timeout_preventsHang() {
        CompletableFuture<String> slow = CompletableFuture.supplyAsync(() -> {
            try { Thread.sleep(10000); } catch (InterruptedException e) { }
            return "done";
        }).orTimeout(500, TimeUnit.MILLISECONDS);

        assertThatThrownBy(slow::join)
            .isInstanceOf(CompletionException.class)
            .hasCauseInstanceOf(TimeoutException.class);
        // Thread freed after 500ms, not 10 seconds!
    }
}
